<script setup lang="ts">
    definePageMeta({middleware:['auth','admin']});
    const {request}=useApi();
    const from=ref(new Date(Date.now()-30*86400000).toISOString().slice(0,10));
    const to=ref(new Date().toISOString().slice(0,10));const [sales,top]=await Promise.all([useAsyncData('sales',()=>request<any>(`/reports/sales?from=${from.value}&to=${to.value}&group_by=day`)),useAsyncData('top',()=>request<any>(`/reports/top-products?from=${from.value}&to=${to.value}&limit=10`))]);</script><template><section><h1 class="text-2xl font-bold mb-4">Sales Reports</h1><div class="flex gap-3 mb-5"><input v-model="from" type="date" class="border p-2"><input v-model="to" type="date" class="border p-2"></div><h2 class="font-bold">Sales by period</h2><table class="w-full bg-white mb-8"><tr><th>Period</th><th>Orders</th><th>Revenue</th></tr><tr v-for="r in sales.data.value?.data"><td>{{r.period}}</td><td>{{r.total_orders}}</td><td>{{r.revenue}}</td></tr></table><h2 class="font-bold">Top products</h2><table class="w-full bg-white"><tr><th>Product</th><th>Qty sold</th><th>Revenue</th></tr><tr v-for="p in top.data.value?.data"><td>{{p.product_name}}</td><td>{{p.quantity_sold}}</td><td>{{p.revenue}}</td></tr></table></section></template>
